// =============================================================================
// Cosmos DB Provider – EF Core 9 Breaking Change Fixes
// Apply these patterns in your Cosmos DB project.
// =============================================================================

using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

// --- FIX 1: Discriminator property renamed from "Discriminator" to "$type" ---
// Existing documents use "Discriminator". Configure explicitly to preserve compatibility.

// --- FIX 2: id property no longer contains discriminator prefix ---
// EF Core 8 stored id as "Session|123"; EF Core 9 stores "123".
// Use HasRootDiscriminatorInJsonId(true) so existing documents remain accessible.

class CosmosContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Preserve old discriminator property name for existing documents
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Preserve old compound id format ("Session|123") for existing documents
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = default!;
    public string Title { get; set; } = default!;
}

// --- FIX 3: Sync I/O no longer supported on Cosmos DB provider ---
// Synchronous methods (ToList, SaveChanges, etc.) now throw.
// Replace with async equivalents.

class CosmosRepository
{
    // BEFORE (throws in EF Core 9):
    // List<Session> GetAll(CosmosContext db) => db.Sessions.ToList();
    // void Save(CosmosContext db) => db.SaveChanges();

    // AFTER: use async equivalents
    async Task<List<Session>> GetAllAsync(CosmosContext db)
        => await db.Sessions.ToListAsync();

    async Task SaveAsync(CosmosContext db)
        => await db.SaveChangesAsync();
}

